import React, { useEffect, useState } from "react";
import Swal from "sweetalert2";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "../ui/dialog";
import { Button } from "../ui/button";
import inspectionService from "../../services/inspection.service";

export const InspectionCreateModal = ({ open, onClose, companyId, orgId, onCreated }) => {
  const [types, setTypes] = useState([]);
  const [form, setForm] = useState({ inspection_type_id: "", inspection_number: "",
    scheduled_date: "", location: "", assigned_to_id: "", start_time: "", end_time: "",
    elaborated_by: "", elaborated_role: "", reviewed_by: "", reviewed_role: "",
    approved_by: "", approved_role: "" });
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    if (open && orgId) {
      inspectionService.getTypes(orgId, true)
        .then(data => { setTypes(data); if (data.length > 0) setForm(f => ({...f, inspection_type_id: String(data[0].id)})); })
        .catch(() => setTypes([]));
    }
  }, [open, orgId]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.inspection_type_id) return;
    setSubmitting(true);
    try {
      const payload = {
        inspection_type_id: Number(form.inspection_type_id),
        inspection_number: form.inspection_number || null,
        scheduled_date: form.scheduled_date || null,
        location: form.location || null,
        start_time: form.start_time || null,
        end_time: form.end_time || null,
        elaborated_by: form.elaborated_by || null,
        elaborated_role: form.elaborated_role || null,
        reviewed_by: form.reviewed_by || null,
        reviewed_role: form.reviewed_role || null,
        approved_by: form.approved_by || null,
        approved_role: form.approved_role || null,
      };
      const ins = await inspectionService.create(companyId, payload);
      onCreated(ins);
      onClose();
    } catch (err) {
      Swal.fire({ icon: "error", title: "No se pudo crear la inspección",
        text: err.response?.data?.detail || "Intenta nuevamente", confirmButtonColor: "#16a34a" });
    } finally { setSubmitting(false); }
  };

  const f = (field) => ({
    value: form[field],
    onChange: (e) => setForm(p => ({...p, [field]: e.target.value})),
    className: "w-full px-4 py-2.5 rounded-lg border border-gray-200 text-sm focus:border-green-500 focus:ring-2 focus:ring-green-100 outline-none transition-all",
  });

  return (
    <Dialog open={open} onOpenChange={(v) => !v && onClose()}>
      <DialogContent className="sm:max-w-lg max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Nueva Inspección</DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4 mt-2">
          <div>
            <label className="block text-xs font-medium text-gray-500 uppercase tracking-wide mb-1.5">Tipo de inspección *</label>
            <select value={form.inspection_type_id} onChange={e => setForm(p => ({...p, inspection_type_id: e.target.value}))}
              className="w-full px-4 py-2.5 rounded-lg border border-gray-200 text-sm focus:border-green-500 outline-none">
              {types.length === 0
                ? <option value="">No hay tipos configurados</option>
                : types.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
            </select>
            {types.length === 0 && (
              <p className="text-xs text-amber-600 mt-1">
                El Supervisor debe configurar primero los tipos de inspección en Configuración → Tipos de Inspección.
              </p>
            )}
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-medium text-gray-500 uppercase tracking-wide mb-1.5">N° Inspección</label>
              <input {...f("inspection_number")} placeholder="1" />
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-500 uppercase tracking-wide mb-1.5">Fecha</label>
              <input type="date" {...f("scheduled_date")} />
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-500 uppercase tracking-wide mb-1.5">Inicio</label>
              <input {...f("start_time")} placeholder="10H00" />
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-500 uppercase tracking-wide mb-1.5">Fin</label>
              <input {...f("end_time")} placeholder="11H00" />
            </div>
          </div>

          <div>
            <label className="block text-xs font-medium text-gray-500 uppercase tracking-wide mb-1.5">Lugar</label>
            <input {...f("location")} placeholder="Ej: Área de producción" />
          </div>

          <hr className="border-gray-100" />
          <p className="text-xs font-semibold text-gray-600">Firmantes del informe</p>

          {[
            ["elaborated_by", "elaborated_role", "Elaborado por"],
            ["reviewed_by",   "reviewed_role",   "Revisado por"],
            ["approved_by",   "approved_role",   "Aprobado por"],
          ].map(([nameField, roleField, label]) => (
            <div key={nameField} className="grid grid-cols-2 gap-3">
              <div>
                <label className="block text-xs font-medium text-gray-400 mb-1">{label}</label>
                <input {...f(nameField)} placeholder="Nombre completo" />
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-400 mb-1">Cargo</label>
                <input {...f(roleField)} placeholder="Cargo / rol" />
              </div>
            </div>
          ))}

          <div className="flex justify-end gap-3 pt-2">
            <Button type="button" variant="outline" onClick={onClose}>Cancelar</Button>
            <Button type="submit" disabled={submitting || !form.inspection_type_id || types.length === 0}
              className="bg-green-600 hover:bg-green-700 text-white disabled:opacity-60">
              {submitting ? "Creando..." : "Crear inspección"}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
};
export default InspectionCreateModal;
